// The German deck in the "Pixelstil" (ADR 0010, 0014): flat pixel art on a
// 33 × 49.5 grid, one art pixel = 2 × 2 CSS px at the 66 × 99 hand size.
// The art is generated by tools/cardart/ into ./pixelcards.gen.ts and
// turned into a hidden sprite of <symbol>s at build time (./sprite.ts,
// web/sprite/plugin.ts); cards only reference the symbols with <use>,
// which keeps the DOM small. This module puts the sprite files into the
// document and names the symbols. Pure drawing, no rules.
//
// The card's frame (1 px dark line, hard shadow) comes from CSS and lies
// outside the art, so the art keeps its integer scale.

import { RARE_SPRITE_URL, SPRITE_URL, UNDEAD } from 'virtual:stammtisch-sprite';
import type { Rank, Suit } from '../types';
import { ICON_MODS } from './fxart';
import { suitCode } from './deck';

export { PAPER, SUITS, suitCode } from './deck';

/** Icons of the card modifications (./fxart.ts), for lists beside the cards. */
export function modIconId(mod: string): string {
  return ICON_MODS.includes(mod) ? `m-${mod}` : 'm-other';
}

/** Symbol id of a face's picture. */
export function faceId(suit: Suit, rank: Rank): string {
  return `f-${suitCode(suit)}${rank}`;
}

/** Symbol id of a face's corner index. */
export function indexId(suit: Suit, rank: Rank): string {
  return `x-${suitCode(suit)}${rank}`;
}

/** Symbol id of the face for tiny cards (index letter and sign, big). */
export function smallFaceId(suit: Suit, rank: Rank): string {
  return `t-${suitCode(suit)}${rank}`;
}

/** Symbol id of the "Untot" picture of a card (zombie figure, rotten pips), or null if there is none. */
export function undeadFaceId(suit: Suit, rank: Rank): string | null {
  const id = `${suitCode(suit)}${rank}`;
  if (!UNDEAD_SET.has(id)) return null;
  ensureRareSprite();
  return `u-${id}`;
}

/** Symbol id of the "Doppelgänger" picture of a card (its mirror image, DG-A). */
export function mirrorFaceId(suit: Suit, rank: Rank): string {
  ensureRareSprite();
  return `d-${suitCode(suit)}${rank}`;
}

/**
 * Symbol ids of a "Wandelkarte" face: picture, corner index, tiny face.
 * Open (no suit): the harlequin; settled into `suit`: the picture in that
 * suit's shades with the suit's normal index and tiny face.
 */
export function wildFaceIds(rank: Rank, suit: Suit | null = null): { picture: string; index: string; small: string } {
  ensureRareSprite();
  if (suit) return { picture: `ws-${suitCode(suit)}${rank}`, index: indexId(suit, rank), small: smallFaceId(suit, rank) };
  return { picture: `w-${rank}`, index: `wx-${rank}`, small: `wt-${rank}` };
}

export function suitId(suit: Suit): string {
  return `s-${suitCode(suit)}`;
}

// ---------------------------------------------------------------- sprite

const UNDEAD_SET = new Set(UNDEAD);

let main: Promise<void> | null = null;

/** A sprite file as text; null (with a warning) if it does not load (cards then show blank faces). */
async function fetchSvg(url: string): Promise<string | null> {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.text();
  } catch (err) {
    console.warn('sprite failed to load', url, err);
    return null;
  }
}

function insert(svg: string): void {
  document.body.insertAdjacentHTML('afterbegin', svg);
}

/** Put the main sprite into the document once (resolves when it is in). */
export function installSprite(): Promise<void> {
  if (typeof document === 'undefined') return Promise.resolve();
  main ??= fetchSvg(SPRITE_URL).then((svg) => {
    if (svg) insert(svg);
  });
  return main;
}

// The rare sprite (Doppelgänger, Untot, Wandelkarte faces, about 1000
// nodes) is fetched in idle time after boot but only goes into the
// document when a card first needs one of its symbols: most evenings
// never do. The ids above ask for it while the card's HTML is built, so
// with the file fetched the symbols are in before the card is.
let rareFetch: Promise<void> | null = null;
let rareText: string | null = null;
let rareWanted = false;
let rareIn = false;

function putRare(): void {
  if (rareIn || !rareText) return;
  rareIn = true;
  insert(rareText);
  rareText = null;
}

/** Fetch the rare sprite in advance (it goes into the document on first use). */
export function prefetchRareSprite(): Promise<void> {
  if (typeof document === 'undefined') return Promise.resolve();
  rareFetch ??= fetchSvg(RARE_SPRITE_URL).then((svg) => {
    rareText = svg;
    if (rareWanted) putRare();
  });
  return rareFetch;
}

/**
 * A card uses a symbol of the rare sprite: put it into the document now
 * if it is fetched, else as soon as it is (a <use> drawn before fills in
 * then).
 */
export function ensureRareSprite(): void {
  if (rareIn || typeof document === 'undefined') return;
  rareWanted = true;
  if (rareText) putRare();
  else void prefetchRareSprite();
}
